// ── Language definitions ───────────────────────────────────────────────────────
export const LANGUAGES = [
  { code: "en", label: "English",  nativeLabel: "English",  flagCode: "us", dir: "ltr" },
  { code: "sv", label: "Svenska",  nativeLabel: "Svenska",  flagCode: "se", dir: "ltr" },
] as const;

/** Returns a local flag SVG URL for the given country code */
export function flagUrl(countryCode: string, _width?: number): string {
  return `/flags/${countryCode}.svg`;
}

export type LangCode = (typeof LANGUAGES)[number]["code"];

const STORAGE_KEY = "ceremoney_lang";

